function Review(){const[view,setView]=useState('agenda');return <MemoryRouter><div className="min-h-screen bg-neutral-base p-3"><p className="text-sm">Entorno de pruebas · datos ficticios · no conectado a producción</p><nav className="flex gap-3 py-3">{['agenda','alumnos','profesor'].map(v=><button className="rounded border px-4 py-2" key={v} onClick={()=>setView(v)}>{v}</button>)}</nav>{view==='agenda'?<AgendaPage/>:view==='alumnos'?<StudentList students={[{id:'importado',name:'ALUMNO DE EJEMPLO',phone:'',status:'membresia',studentCategory:'membresia',classesRemaining:7,legacyManualBalance:7,price:120,bonosAsignados:4}]} onUpdate={async()=>{}} onAddStudent={async()=>{}} onRenew={async()=>{}} onDeleteStudent={async()=>{}}/>:<SessionDetailsDialog session={{id:'class-demo',date:'2026-11-18',startTime:'19:00',endTime:'21:00',revision:1,classType:'mesa'} as any} mode="teacher" teachers={[{id:'teacher',name:'Profesor de ejemplo',surname:''}] as any} schedule={[]} exceptions={[]} readOnly={false} onSave={async()=>{setView('agenda');return true;}} onClose={()=>setView('agenda')}/>}</div></MemoryRouter>}createRoot(document.getElementById('root')!).render(<Review/>);